const fetched = $input.all();
const meta = $("Competitor List").all();

const compact = fetched.map((item, i) => {
  const html = (item.json.data || '').toString();
  const nameUrl = meta[i] ? meta[i].json : {};

  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : '';

  const headingMatches = [...html.matchAll(/<h[1-3][^>]*>([\s\S]*?)<\/h[1-3]>/gi)]
    .map(m => m[1].replace(/<[^>]+>/g, '').trim())
    .filter(Boolean)
    .slice(0, 10);

  const textOnly = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    competitor: nameUrl.name || `Competitor ${i + 1}`,
    url: nameUrl.url || '',
    fetched_at: new Date().toISOString(),
    title,
    headings: headingMatches,
    text: textOnly.slice(0, 12000)
  };
});

const prompt = `You are a competitive intelligence analyst. Review the following competitor website snapshots. Produce a concise weekly report in Markdown. For each competitor, summarize notable positioning, product, pricing, campaign, or messaging signals, and cite the URL. Clearly separate observations from assumptions. If there is insufficient evidence, say so.

DATA:
${JSON.stringify(compact, null, 2)}`;

return [{ json: { prompt } }];

